-- GENERATED by tools/gamekit/bundle.py from tools/gamekit/gamekit.lua and apps/riverstead/src/
-- -- edit those files, not this one.
local kit = (function()
-- gamekit: shared pieces for the API 2.9 puzzle games (Lights Out, Peg Solitaire, Nonograms,
-- Knight's Tour). tools/gamekit/bundle.py puts it in front of a game's src/main.lua as
-- `local kit = (function() ... end)()`, since the device has no require for package files.
--
--   kit.W, kit.H                      screen size
--   kit.font(name), kit.width(f, s), kit.line_h(name)
--   kit.short(s, n), kit.drop_last(s), kit.wrap(s, fname, maxw)
--   kit.read(name), kit.write(name, s), kit.kv(s)   ctx.storage helpers ("key=value" lines)
--   kit.now_ms(), kit.refresh()
--   kit.moved()                       count a move (a hook for a periodic full refresh; see below)
--   kit.key_accepted(ev)              side buttons send several events per press: keep one
--   kit.show(m), kit.close(), kit.modal()   a box over the screen: { title, lines, rows, cancel },
--                                     rows = { { {label, fn, enabled}, .. }, .. }
--   kit.draw_modal(gg), kit.tap_modal(x, y) -> true when the box took the tap
--   kit.button(gg, x, y, w, h, label, opts)  a framed button with a centred label
-- Every ctx.* function is a method on this API: colon calls everywhere. Nothing is filled black:
-- large black areas ghost on e-ink, and the host draws text black even when asked for white.

local kit = {}
kit.W, kit.H = 480, 800

function kit.font(name) return ctx.fonts and ctx.fonts[name] end
function kit.width(f, s)
  local ok, w = pcall(function() return f:measure(s) end)
  return (ok and type(w) == 'number') and w or #s * 11
end
function kit.line_h(name)
  local ok, h = pcall(function() return kit.font(name).line_height end)
  return (ok and tonumber(h)) or (name == 'large' and 30 or name == 'small' and 20 or 24)
end

-- drop the last character (a whole UTF-8 sequence)
function kit.drop_last(s) return (s:gsub('[%z\1-\127\192-\255][\128-\191]*$', '')) end
function kit.short(s, n)
  s = tostring(s)
  if #s <= n then return s end
  local t = s:sub(1, n)
  while #t > n - 1 or (#t > 0 and t:sub(-1):byte() >= 128 and not utf8.len(t)) do t = kit.drop_last(t) end
  return t .. '~'
end
-- word wrap on ASCII spaces only (%s may also match 0xA0, the second byte of some letters)
function kit.wrap(s, fname, maxw)
  local f, out = kit.font(fname), {}
  for para in (tostring(s) .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for word in para:gmatch('[^ \t]+') do
      local cand = line == '' and word or (line .. ' ' .. word)
      if line ~= '' and kit.width(f, cand) > maxw then out[#out + 1] = line; line = word else line = cand end
    end
    out[#out + 1] = line
  end
  return out
end

function kit.read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
function kit.write(name, s) pcall(function() ctx.storage:write(name, s) end) end
function kit.kv(s)
  local t = {}
  for k, v in (s or ''):gmatch('([%w_]+)=([^\n]*)') do t[k] = (v:gsub('%s+$', '')) end
  return t
end

function kit.now_ms() local ok, t = pcall(function() return ctx.clock:millis() end); return ok and tonumber(t) or nil end
function kit.refresh() pcall(function() ctx:invalidate() end) end

-- e-ink full refresh: API 0.8 had ctx.display:full_refresh(); API 2.9 only offers
-- ctx:defer_full_refresh(n), which on the device (26102401) did not trigger one, and which by its
-- name may rather postpone the host's own periodic refresh. So nothing is asked for: the games
-- showed no ghosting problem without it. kit.moved() stays as the place to add one.
local moves = 0
function kit.moved() moves = moves + 1 end

local KEY_GAP_MS = 250
local last_key, last_key_ms = nil, nil
function kit.key_accepted(ev)
  local ph = ev.phase or ev.action or ev.state
  if ph == 'up' or ph == 'release' or ph == 'released' or ev.pressed == false or ev.down == false then return false end
  local t = tonumber(ev.time_ms) or kit.now_ms()
  if t and last_key == ev.key and last_key_ms and t - last_key_ms >= 0 and t - last_key_ms < KEY_GAP_MS then return false end
  last_key, last_key_ms = ev.key, t
  return true
end

------------------------------------------------------------------ boxes

local BOX_X, ROW_H, GAP = 20, 56, 10
local BOX_W = kit.W - 40      -- refreshed in layout(): an app may set kit.W, kit.H for a landscape screen
local modal = nil

function kit.show(m) modal = m end
function kit.close() modal = nil end
function kit.modal() return modal end

local function layout(m)
  BOX_W = kit.W - 40
  local lines = {}
  if m.title then for _k, l in ipairs(kit.wrap(m.title, 'medium', BOX_W - 40)) do lines[#lines + 1] = { l, 'medium' } end end
  for _k, s in ipairs(m.lines or {}) do
    for _j, l in ipairs(kit.wrap(s, 'small', BOX_W - 40)) do lines[#lines + 1] = { l, 'small' } end
  end
  local th = 0
  for _k, l in ipairs(lines) do th = th + kit.line_h(l[2]) + 4 end
  local h = 20 + th + 14 + #m.rows * (ROW_H + GAP) + 10
  local y = math.max(60, math.floor((kit.H - h) / 2))
  local btns, by = {}, y + 20 + th + 14
  for _k, row in ipairs(m.rows) do
    local n = #row
    local bw = math.floor((BOX_W - 40 - (n - 1) * GAP) / n)
    for k, btn in ipairs(row) do
      btns[#btns + 1] = { x = BOX_X + 20 + (k - 1) * (bw + GAP), y = by, w = bw, h = ROW_H, b = btn }
    end
    by = by + ROW_H + GAP
  end
  return lines, btns, y, h
end

function kit.button(gg, x, y, w, h, label, opts)
  opts = opts or {}
  local f = kit.font(opts.font or 'medium')
  gg:rect(x, y, w, h, { line_width = opts.line_width or 2 })
  local s = tostring(label)
  while #s > 1 and kit.width(f, s) > w - 10 do s = kit.drop_last(s) end
  gg:text(x + math.floor((w - kit.width(f, s)) / 2), y + math.floor((h - kit.line_h(opts.font or 'medium')) / 2), s, { font = f })
end

function kit.draw_modal(gg)
  local lines, btns, y, h = layout(modal)
  -- paper first, so the page under the box does not show through it
  gg:rect(BOX_X, y, BOX_W, h, { fill = true, color = 0 })
  gg:rect(BOX_X, y, BOX_W, h)
  gg:rect(BOX_X + 3, y + 3, BOX_W - 6, h - 6)
  local ty = y + 20
  for _k, l in ipairs(lines) do gg:text(BOX_X + 20, ty, l[1], { font = kit.font(l[2]) }); ty = ty + kit.line_h(l[2]) + 4 end
  for _k, bt in ipairs(btns) do
    local enabled = bt.b[3] ~= false
    kit.button(gg, bt.x, bt.y, bt.w, bt.h, enabled and bt.b[1] or ('(' .. bt.b[1] .. ')'), { line_width = enabled and 2 or 1 })
  end
end

function kit.tap_modal(x, y)
  if not modal then return false end
  local _l, btns, my, mh = layout(modal)
  for _k, bt in ipairs(btns) do
    if x >= bt.x and x < bt.x + bt.w and y >= bt.y and y < bt.y + bt.h then
      if bt.b[3] ~= false then bt.b[2]() end
      return true
    end
  end
  if (y < my or y > my + mh) and modal.cancel then modal.cancel() end
  return true
end

return kit
end)()

-- Riverstead for XTOS Licorice (uses tools/gamekit): a village in a river valley, guided for ten years,
-- one month a turn. The valley is made anew from a seed every game; where a building stands changes
-- what it gives; named villagers live, marry, grow old and leave; events come with the seasons; and
-- the village grows one of four ways, each with its own ending.
--
-- The game logic lives in package files under game/ (loaded with _G.require, since the bundle's local
-- require shadows the host's). village.txt keeps the game, chronicle.txt the finished ones, prefs.txt
-- the settings. The map is drawn into an offscreen layer (in chunks: the reader keeps about 1024
-- commands per layer:draw call) whenever it changes; without layers it is drawn plainly.

local W, H = kit.W, kit.H
local BTN_Y, BTN_H = 724, 60
local MAP_X, MAP_Y, TILE = 20, 84, 40

local function mod(name) return (_G.require('game.' .. name)) end
local Rn, Save = mod('rng'), mod('save')
local T, V, R, P, E, EL, S, B
local function load_game_modules()
  if S then return end
  T = mod('text'); V = mod('valley')(Rn); R = mod('rules')(Rn, V); P = mod('people')(Rn, R, T)
  E = mod('events'); EL = mod('event_list')(Rn, R, P, T); S = mod('sim')(Rn, V, R, P, E, T, EL)
end

local screen = 'title'
local ERR = nil
local hits = {}                  -- tap regions of the last frame: { x, y, w, h, fn }
local state = nil
local prefs = { diff = 'normal' }
local sel = nil                  -- the selected tile
local placing = nil              -- the kind being placed
local layer, layer_ok, map_dirty = nil, false, true
local page = 1
local who = nil                  -- the person on the person card

------------------------------------------------------------------ drawing helpers

local function hit(x, y, w, h, fn) hits[#hits + 1] = { x = x, y = y, w = w, h = h, fn = fn } end

local function button(gg, x, y, w, h, label, fn, opts)
  kit.button(gg, x, y, w, h, label, opts)
  hit(x, y, w, h, fn)
end

local function bottom_row(gg, list)
  local n, gap = #list, 8
  local bw = (W - 32 - gap * (n - 1)) // n
  for k, b in ipairs(list) do button(gg, 16 + (k - 1) * (bw + gap), BTN_Y, bw, BTN_H, b[1], b[2]) end
end

local function fit(s, f, w)
  s = tostring(s)
  if kit.width(f, s) <= w then return s end
  while #s > 1 and kit.width(f, s .. '…') > w do s = kit.drop_last(s) end
  return s .. '…'
end

local function header(gg, title, sub)
  local f = kit.font('large')
  gg:text(16, 10, fit(title, f, W - 32), { font = f })
  if sub then gg:text(16, 50, fit(sub, kit.font('small'), W - 32), { font = kit.font('small') }) end
  gg:line(16, 80, W - 16, 80)
end

local function para(gg, s, x, y, y_max, fname)
  fname = fname or 'small'
  local lh = kit.line_h(fname) + 2
  for _, l in ipairs(kit.wrap(s, fname, W - x - 16)) do
    if y + lh > y_max then return y end
    gg:text(x, y, l, { font = kit.font(fname) })
    y = y + lh
  end
  return y
end

local function box(title, lines, rows, cancel)
  kit.show({ title = title, lines = lines, rows = rows, cancel = cancel })
end

------------------------------------------------------------------ saving

local saved = nil                -- the saved game: nil (none), 'playing', 'over' or 'bad'

local function read_saved()
  local s = kit.read('village.txt')
  if type(s) ~= 'string' or #s <= 2 then saved = nil; return end
  local ok, st = pcall(Save.decode, s)
  if not ok or type(st) ~= 'table' or not st.valley then saved = 'bad'; return end
  saved = st.over and 'over' or 'playing'
end

local function has_game() return saved ~= nil end

local function save()
  kit.write('prefs.txt', Save.encode(prefs))
  if state then kit.write('village.txt', Save.encode(state)); saved = state.over and 'over' or 'playing' end
end

-- a tile's name on the map: its column letter and row number (A1 top left)
local function coord(i) return string.char(64 + (i - 1) % 11 + 1) .. ((i - 1) // 11 + 1) end

------------------------------------------------------------------ the map

local function tile_xy(i)
  local x, y = (i - 1) % 11, (i - 1) // 11
  return MAP_X + x * TILE, MAP_Y + y * TILE
end

local function tri(g, x, y, s, fill) g:polygon({ x, y + s, x + s // 2, y, x + s, y + s }, { fill = fill }) end

local function draw_terrain(g, i, x, y)
  local v = state.valley
  local t = v.t[i]
  if t == 'fertile' then
    for k = 0, 2 do g:line(x + 8, y + 12 + k * 8, x + 32, y + 12 + k * 8) end
  elseif t == 'forest' then
    tri(g, x + 5, y + 8, 14, true); tri(g, x + 20, y + 18, 14, true)
  elseif t == 'rock' then
    tri(g, x + 6, y + 10, 22, false); g:line(x + 22, y + 32, x + 34, y + 20)
  elseif t == 'marsh' then
    for k = 0, 2 do g:line(x + 8 + k * 10, y + 30, x + 12 + k * 10, y + 20) end
  elseif t == 'river' then
    local n = v.wide[i] and 3 or 2
    for k = 1, n do
      local yy = y + k * 40 // (n + 1)
      g:polyline({ x + 4, yy, x + 14, yy - 4, x + 26, yy + 4, x + 36, yy }, {})
    end
    for _, f in ipairs(v.ford) do
      if f == i then g:line(x + 4, y + 6, x + 36, y + 6, { line_width = 2 }); g:line(x + 4, y + 34, x + 36, y + 34, { line_width = 2 }) end
    end
  end
  if v.special == i then
    g:polygon({ x + 20, y + 6, x + 24, y + 16, x + 34, y + 17, x + 26, y + 24, x + 29, y + 34, x + 20, y + 28,
                x + 11, y + 34, x + 14, y + 24, x + 6, y + 17, x + 16, y + 16 }, {})
  end
end

-- a building: a white block with a frame and a small shape for its kind; one being built is dashed
local SHAPE = {
  house = function(g, x, y) g:polygon({ x + 8, y + 20, x + 20, y + 8, x + 32, y + 20 }, { fill = true }); g:rect(x + 11, y + 20, 18, 13, { line_width = 2 }) end,
  field = function(g, x, y) for k = 0, 3 do g:line(x + 8, y + 9 + k * 7, x + 32, y + 9 + k * 7, { line_width = 2 }) end end,
  fisher = function(g, x, y) g:polygon({ x + 8, y + 20, x + 20, y + 13, x + 28, y + 20, x + 20, y + 27 }, { fill = true }); tri(g, x + 26, y + 14, 10, false) end,
  woodcutter = function(g, x, y) g:line(x + 12, y + 32, x + 28, y + 10, { line_width = 3 }); g:rect(x + 24, y + 8, 9, 7, { fill = true }) end,
  quarry = function(g, x, y) tri(g, x + 7, y + 14, 14, false); tri(g, x + 19, y + 14, 14, false) end,
  toolmaker = function(g, x, y) g:line(x + 20, y + 14, x + 20, y + 32, { line_width = 3 }); g:rect(x + 11, y + 9, 18, 6, { fill = true }) end,
  storehouse = function(g, x, y) g:rect(x + 9, y + 9, 22, 22, { line_width = 2 }); g:line(x + 9, y + 9, x + 31, y + 31); g:line(x + 31, y + 9, x + 9, y + 31) end,
  well = function(g, x, y) g:circle(x + 20, y + 22, 9, { line_width = 2 }); g:line(x + 10, y + 10, x + 30, y + 10, { line_width = 2 }) end,
  herbalist = function(g, x, y) g:rect(x + 17, y + 9, 6, 22, { fill = true }); g:rect(x + 9, y + 17, 22, 6, { fill = true }) end,
  chapel = function(g, x, y) g:polygon({ x + 13, y + 33, x + 13, y + 16, x + 20, y + 9, x + 27, y + 16, x + 27, y + 33 }, {}); g:line(x + 20, y + 3, x + 20, y + 12) end,
  levee = function(g, x, y) g:rect(x + 4, y + 16, 32, 8, { fill = true }) end,
  market = function(g, x, y) g:polyline({ x + 6, y + 16, x + 12, y + 10, x + 18, y + 16, x + 24, y + 10, x + 30, y + 16, x + 34, y + 12 }, { line_width = 2 }); g:rect(x + 9, y + 18, 22, 13, { line_width = 2 }) end,
  tradingpost = function(g, x, y) g:line(x + 13, y + 33, x + 13, y + 7, { line_width = 2 }); g:polygon({ x + 14, y + 7, x + 31, y + 12, x + 14, y + 17 }, { fill = true }) end,
  wharf = function(g, x, y) g:circle(x + 20, y + 11, 4, {}); g:line(x + 20, y + 15, x + 20, y + 32, { line_width = 2 }); g:arc(x + 20, y + 22, 10, 30, 150, { line_width = 2 }) end,
  mill = function(g, x, y) g:line(x + 8, y + 8, x + 32, y + 32, { line_width = 2 }); g:line(x + 32, y + 8, x + 8, y + 32, { line_width = 2 }); g:circle(x + 20, y + 20, 5, { fill = true }) end,
  barn = function(g, x, y) g:polygon({ x + 5, y + 20, x + 20, y + 6, x + 35, y + 20 }, { fill = true }); g:rect(x + 8, y + 20, 24, 13, { line_width = 2 }) end,
  bakery = function(g, x, y) g:arc(x + 20, y + 26, 13, 180, 360, { line_width = 3 }); g:line(x + 7, y + 26, x + 33, y + 26, { line_width = 2 }) end,
  smithy = function(g, x, y) g:polygon({ x + 6, y + 14, x + 34, y + 14, x + 28, y + 22, x + 24, y + 22, x + 26, y + 32, x + 14, y + 32, x + 16, y + 22, x + 12, y + 22 }, { fill = true }) end,
  pottery = function(g, x, y) g:circle(x + 20, y + 24, 9, { fill = true }); g:rect(x + 16, y + 8, 8, 8, { line_width = 2 }) end,
  weaving = function(g, x, y) for k = 0, 2 do g:line(x + 12 + k * 8, y + 8, x + 12 + k * 8, y + 32) end; g:line(x + 8, y + 15, x + 32, y + 15); g:line(x + 8, y + 25, x + 32, y + 25) end,
  shrine = function(g, x, y) g:circle(x + 20, y + 20, 10, { line_width = 3 }); g:circle(x + 20, y + 20, 3, { fill = true }) end,
  temple = function(g, x, y) tri(g, x + 7, y + 6, 26, true); for k = 0, 2 do g:line(x + 11 + k * 9, y + 20, x + 11 + k * 9, y + 33, { line_width = 2 }) end end,
  hostel = function(g, x, y) g:rect(x + 7, y + 18, 26, 9, { line_width = 2 }); g:rect(x + 7, y + 13, 7, 6, { fill = true }); g:line(x + 7, y + 27, x + 7, y + 32); g:line(x + 33, y + 27, x + 33, y + 32) end,
}

local function draw_building(g, i, x, y)
  local b = state.b[i]
  g:rect(x + 2, y + 2, TILE - 4, TILE - 4, { fill = true, color = 0 })
  if b.left > 0 then
    for k = 0, 3 do
      g:line(x + 2 + k * 10, y + 2, x + 7 + k * 10, y + 2)
      g:line(x + 2 + k * 10, y + TILE - 3, x + 7 + k * 10, y + TILE - 3)
    end
  else
    g:rect(x + 2, y + 2, TILE - 4, TILE - 4, { line_width = 2 })
  end
  local f = SHAPE[b.kind]
  if f then f(g, x, y) end
end

-- the map into its layer, in four calls of a few rows each
local function rebuild_layer()
  if not layer_ok then return end
  local rows = { { 1, 3 }, { 4, 6 }, { 7, 9 }, { 10, 11 } }
  for k, rr in ipairs(rows) do
    local ok, err = pcall(function()
      local _, why = layer:draw(function(g)
        if k == 1 then g:clear(0) end
        for y = rr[1], rr[2] do
          for x = 1, 11 do
            local i = (y - 1) * 11 + x
            local px, py = (x - 1) * TILE, (y - 1) * TILE
            if state.b[i] then draw_building(g, i, px, py) else draw_terrain(g, i, px, py) end
          end
        end
        if k == 1 then g:rect(0, 0, 440, 440, {}) end
      end)
      if why then error(why) end
    end)
    if not ok then layer_ok = false; ERR = nil; return end
    local _ = err
  end
  map_dirty = false
end

local function ensure_layer()
  if layer then return end
  local ok, l = pcall(function() return ctx.layers and ctx.layers:create(440, 440) end)
  if ok and l then layer, layer_ok = l, true else layer, layer_ok = nil, false end
end

local function mark_map() map_dirty = true end

-- without layers: rivers, forests and buildings as plain shapes, few commands
local function draw_map_plain(gg)
  gg:rect(MAP_X, MAP_Y, 440, 440, {})
  local v = state.valley
  local ford = {}
  for _, f in ipairs(v.ford) do ford[f] = true end
  for i = 1, 121 do
    local x, y = tile_xy(i)
    local t = v.t[i]
    if state.b[i] then gg:rect(x + 4, y + 4, TILE - 8, TILE - 8, { line_width = state.b[i].left > 0 and 1 or 3 })
    elseif t == 'river' then gg:line(x + 4, y + 20, x + 36, y + 20, { line_width = ford[i] and 1 or 3 })
    elseif t == 'forest' then tri(gg, x + 12, y + 12, 16, true)
    elseif t == 'rock' then tri(gg, x + 10, y + 12, 18, false)
    elseif t == 'fertile' then gg:line(x + 10, y + 20, x + 30, y + 20)
    elseif t == 'marsh' then gg:line(x + 12, y + 28, x + 16, y + 18); gg:line(x + 24, y + 28, x + 28, y + 18) end
    if v.special == i and not state.b[i] then gg:circle(x + 20, y + 20, 8, { line_width = 2 }) end
  end
end

------------------------------------------------------------------ the game

local function new_seed()
  local s = rawget(_G, 'riverstead_seed')
  if s then return s end
  local t = math.floor(kit.now_ms() or 1) % 100000
  return t * 7919 + math.random(1, 1000000000)
end

local function month_name(m)
  return T.MONTHS[R.moy(m)] .. ', year ' .. R.year(m) .. ' · ' .. R.season(m)
end

local SCREENS = {}

local show_event                  -- set below

local function after_month(rep)
  local lines = {}
  if rep.harvest and rep.harvest > 0 then lines[#lines + 1] = 'The harvest brought in ' .. rep.harvest .. ' food.' end
  for _, k in ipairs(rep.built or {}) do lines[#lines + 1] = 'The ' .. R.BUILD[k].name:lower() .. ' is finished.' end
  for k = 1, math.min(5, #(rep.lines or {})) do lines[#lines + 1] = rep.lines[k] end
  if rep.hunger and rep.hunger > 0 then lines[#lines + 1] = 'There was not enough food. People went hungry.' end
  if state.over then
    screen = 'end'
    save()
    if #lines > 0 then box(month_name(rep.month), lines, { { { 'Go on', kit.close } } }, kit.close) end
    return
  end
  S.begin_month(state, Rn.new(Rn.mix(state.seed, state.month * 7 + 1)))
  save()
  if #lines > 0 then
    box(month_name(rep.month), lines, { { { 'Go on', function() kit.close(); show_event() end } } },
      function() kit.close(); show_event() end)
  else show_event() end
end

local function next_month()
  pcall(function() ctx.budget:extend() end)
  local rep = S.next_month(state, Rn.new(Rn.mix(state.seed, state.month)))
  mark_map()
  after_month(rep)
end

show_event = function()
  if not state or not state.event then return end
  local def = S.event_def(state)
  if not def then state.event = nil; return end
  local vars = state.event.vars
  local rr = Rn.new(Rn.mix(state.seed, state.month * 13))
  -- the buttons name people by their first name, so the labels fit
  local short = {}
  for k, x in pairs(vars) do short[k] = x end
  for _, k in ipairs({ 'who', 'who2', 'kid', 'elder', 'unhappy', 'woodsman', 'healer', 'builder' }) do
    if type(short[k]) == 'string' then short[k] = short[k]:match('^(%S+)') end
  end
  local function choose(nn)
    kit.close()
    local text = S.answer(state, nn, Rn.new(Rn.mix(state.seed, state.month * 17 + nn)))
    mark_map()
    save()
    if text ~= '' then box('', { text }, { { { 'Go on', kit.close } } }, kit.close) end
  end
  local rows = {}
  for n, c in ipairs(S.offered(state)) do
    local nn = n
    rows[#rows + 1] = { { T.fill(c.label, short), function() choose(nn) end } }
  end
  -- Back gives the safe answer when the event has one; otherwise it waits for a choice
  local safe = S.back_choice(state)
  box(month_name(state.month), { T.event_text(def, vars, rr) }, rows, function() if safe then choose(safe) end end)
end

local function start_game()
  pcall(function() ctx.budget:extend() end)
  load_game_modules()
  state = S.new(new_seed(), prefs.diff or 'normal')
  sel, placing = nil, nil
  ensure_layer()
  mark_map()
  S.begin_month(state, Rn.new(Rn.mix(state.seed, 3)))
  save()
  screen = 'village'
  rebuild_layer()
  show_event()
end

local function continue_game()
  pcall(function() ctx.budget:extend() end)
  load_game_modules()
  local ok, st = pcall(Save.decode, kit.read('village.txt'))
  if not ok or type(st) ~= 'table' or not st.valley then
    state = nil
    box('Continue', { 'The saved village could not be read. Start a new valley instead.' }, { { { 'Close', kit.close } } }, kit.close)
    return
  end
  state = st
  ensure_layer()
  mark_map()
  rebuild_layer()
  screen = state.over and 'end' or 'village'
  if not state.over then show_event() end
end

