local RES_NAME = { food = 'Food', wood = 'Wood', stone = 'Stone', tools = 'Tools', coin = 'Coin' }

local function warnings()
  local out = {}
  -- a harvest is coming only if some field was sown or has people on it
  local harvest = false
  local unstaffed = {}
  for i, b in pairs(state.b) do
    if b.kind == 'field' and (b.sown or #R.workers_of(state, i) > 0) then harvest = true end
    local d = R.BUILD[b.kind]
    if b.left == 0 and d.slots > 0 and #R.workers_of(state, i) == 0 then unstaffed[#unstaffed + 1] = d.name end
  end
  if R.food_warning(state) then
    local fm, mth = R.food_months(state), R.months_to_harvest(state.month)
    out[#out + 1] = 'Food for ' .. fm .. ' month' .. (fm == 1 and '' or 's')
      .. ((harvest and mth > 0) and ('; harvest in ' .. mth) or (harvest and '' or '; no field sown'))
  end
  local sick, sad, building, builders, idle = 0, 0, false, 0, 0
  for _, id in ipairs(P.living(state)) do
    local p = state.people[id]
    if p.health < 30 then sick = sick + 1 end
    if p.happy < 30 then sad = sad + 1 end
    if p.job == 'build' then builders = builders + 1 end
    if p.job == nil and p.age >= 144 then idle = idle + 1 end
  end
  for _, b in pairs(state.b) do if b.left > 0 then building = true end end
  if building and builders == 0 then out[#out + 1] = 'Nobody is building' end
  if #unstaffed > 0 then
    table.sort(unstaffed)
    out[#out + 1] = unstaffed[1] .. (#unstaffed > 1 and (' and ' .. (#unstaffed - 1) .. ' more') or '') .. ': no workers'
  end
  if idle > 0 then out[#out + 1] = idle .. ' idle' end
  if sick > 0 then out[#out + 1] = sick .. ' sick' end
  if sad > 0 then out[#out + 1] = sad .. ' unhappy' end
  return out
end

local function tile_panel(gg, y)
  local v = state.valley
  if placing then
    local name = R.BUILD[placing].name
    if not sel then
      gg:text(16, y, fit('Tap where the ' .. name:lower() .. ' goes.', kit.font('medium'), W - 32), { font = kit.font('medium') })
      button(gg, W - 136, y + 40, 120, 44, 'Cancel', function() placing = nil end, { font = 'small' })
      return
    end
    local ok, why = R.can_place(state, placing, sel)
    if not ok then
      gg:text(16, y, fit(name .. ': ' .. why, kit.font('medium'), W - 32), { font = kit.font('medium') })
      button(gg, W - 136, y + 40, 120, 44, 'Cancel', function() placing, sel = nil, nil end, { font = 'small' })
      return
    end
    local pv = R.yield_preview(state, placing, sel)
    local parts = {}
    for _, k in ipairs(R.RES) do if pv[k] then parts[#parts + 1] = pv[k] .. ' ' .. k end end
    local s = name .. ' here' .. (#parts > 0 and (': about ' .. table.concat(parts, ', ') .. ' a year') or '')
    if placing == 'field' and V.riverside(v, sel) then s = s .. '; floods' end
    if placing == 'house' then
      if V.near(v, sel, 'marsh', 1) > 0 then s = s .. '; damp by the marsh, less healthy' end
      local noisy = false
      for _, j in ipairs(V.around(sel)) do local b = state.b[j]; if b and R.NOISY[b.kind] then noisy = true end end
      if noisy then s = s .. '; noisy' end
    elseif R.NOISY[placing] then
      for _, j in ipairs(V.around(sel)) do local b = state.b[j]; if b and b.kind == 'house' then s = s .. '; noisy for the houses next to it'; break end end
    end
    para(gg, s, 16, y, y + 44, 'small')
    local kind = placing
    local at = sel
    button(gg, 16, y + 46, 140, 44, 'Place', function()
      if not at or not R.can_place(state, kind, at) then return end
      R.place(state, kind, at)
      placing, sel = nil, nil
      -- someone must build it: when nobody is, everyone is put where they fit best
      local builders = 0
      for _, id in ipairs(P.living(state)) do if state.people[id].job == 'build' then builders = builders + 1 end end
      if builders == 0 then P.auto_assign(state) end
      mark_map()
      save()
    end, { font = 'small' })
    button(gg, 168, y + 46, 140, 44, 'Cancel', function() placing, sel = nil, nil end, { font = 'small' })
    return
  end
  if not sel then return end
  local t = v.t[sel]
  local b = state.b[sel]
  local line1 = coord(sel) .. ' · ' .. t
  if v.special == sel then line1 = line1 .. ', the ' .. (v.special_kind == 'spring' and 'old spring' or 'standing stone') end
  if V.riverside(v, sel) then line1 = line1 .. ', by the river' end
  gg:text(16, y, fit(line1, kit.font('small'), W - 32), { font = kit.font('small') })
  if b then
    local d = R.BUILD[b.kind]
    local s = d.name
    if b.left > 0 then s = s .. ': being built, ' .. (b.left + 1) // 2 .. ' builder-month' .. ((b.left + 1) // 2 == 1 and '' or 's') .. ' left'
    elseif d.slots > 0 then s = s .. ': ' .. #R.workers_of(state, sel) .. ' of ' .. d.slots .. ' at work' end
    gg:text(16, y + 24, fit(s, kit.font('medium'), W - 32), { font = kit.font('medium') })
    local i = sel
    button(gg, W - 136, y + 52, 120, 40, 'Demolish', function()
      box('Demolish the ' .. d.name:lower() .. '?', { 'Nothing is given back.' },
        { { { 'Demolish', function() kit.close(); R.demolish(state, i); mark_map(); save() end }, { 'Cancel', kit.close } } }, kit.close)
    end, { font = 'small' })
  end
end

