local function cost_text(d)
  local parts = {}
  for _, k in ipairs(R.RES) do if d.cost[k] then parts[#parts + 1] = d.cost[k] .. ' ' .. k end end
  return #parts > 0 and table.concat(parts, ', ') or 'free'
end

-- why a kind can't be built anywhere now (the first reason found), or nil
local function locked(kind)
  local d = R.BUILD[kind]
  if d.needs and not R.has(state, d.needs) then return 'needs a ' .. R.BUILD[d.needs].name:lower() end
  for _, k in ipairs(R.RES) do if (d.cost[k] or 0) > state.res[k] then return 'not enough ' .. k end end
  for i = 1, 121 do if R.can_place(state, kind, i) then return nil end end
  return 'nowhere to stand'
end

