------------------------------------------------------------------ people

local function job_name(p)
  if p.job == 'build' then return 'builder' end
  if type(p.job) == 'number' and state.b[p.job] then return R.BUILD[state.b[p.job].kind].name:lower() end
  if p.age < 144 then return 'child' end
  return 'idle'
end

local function years(p) return p.age // 12 end

