-- the jobs a person can take: builder, idle, and every finished building with a free place
local function jobs_for(p)
  local out = { { 'Builder', 'build' }, { 'Idle', false } }
  local many = {}
  for _, b in pairs(state.b) do many[b.kind] = (many[b.kind] or 0) + 1 end
  for i = 1, 121 do
    local b = state.b[i]
    if b and b.left == 0 then
      local d = R.BUILD[b.kind]
      if d.slots > 0 and (#R.workers_of(state, i) < d.slots or p.job == i) then
        out[#out + 1] = { d.name .. (many[b.kind] > 1 and (' ' .. coord(i)) or ''), i }
      end
    end
  end
  return out
end
local jpage = 1                  -- the page of the person card's jobs

SCREENS.person = {
  draw = function(gg)
    local p = state.people[who]
    header(gg, p.name, years(p) .. ' years · ' .. job_name(p))
    local y = 92
    local lines = {
      'A ' .. T.SKILL_NAME[p.skill] .. ', skill ' .. p.lv .. ' of 5; ' .. p.trait .. '.',
      'Health ' .. p.health .. ', happiness ' .. p.happy .. '.',
    }
    if p.spouse and state.people[p.spouse] then lines[#lines + 1] = 'Married to ' .. state.people[p.spouse].name .. '.' end
    local kids = {}
    for _, q in pairs(state.people) do
      if (q.mother == p.id or q.father == p.id) and q.alive and not q.gone then kids[#kids + 1] = q.name:match('^(%S+)') end
    end
    table.sort(kids)
    if #kids > 0 then lines[#lines + 1] = 'Children: ' .. table.concat(kids, ', ') .. '.' end
    for _, s in ipairs(p.story or {}) do lines[#lines + 1] = s:gsub('^%l', string.upper) .. '.' end
    for _, l in ipairs(lines) do y = para(gg, l, 16, y, 380) + 2 end
    if p.age < 144 then
      para(gg, 'Too young to work.', 16, math.max(y + 10, 400), 440)
    else
      gg:text(16, math.max(y + 10, 392), 'Job', { font = kit.font('small') })
      y = math.max(y + 36, 418)
      local f = kit.font('small')
      -- lay the jobs out in pages that fit above the buttons
      local pages, x, yy, top = { {} }, 16, y, y
      for _, j in ipairs(jobs_for(p)) do
        local w = math.min(W - 32, kit.width(f, j[1]) + 24)
        if x + w > W - 16 then x, yy = 16, yy + 48 end
        if yy + 44 > BTN_Y - 4 then pages[#pages + 1] = {}; x, yy = 16, top end
        local pg = pages[#pages]
        pg[#pg + 1] = { j, x, yy, w }
        x = x + w + 8
      end
      if jpage > #pages then jpage = 1 end
      for _, c in ipairs(pages[jpage]) do
        local job = c[1][2]
        local here = (job == false and p.job == nil) or p.job == job
        button(gg, c[2], c[3], c[4], 42, fit(c[1][1], f, c[4] - 12), function() p.job = job or nil; save() end,
          { font = 'small', line_width = here and 4 or 1 })
      end
      if #pages > 1 then
        bottom_row(gg, { { 'More jobs', function() jpage = jpage % #pages + 1 end }, { 'Back', function() screen = 'people' end } })
        return
      end
    end
    bottom_row(gg, { { 'Back', function() screen = 'people' end } })
  end,
  back = function() screen = 'people'; return true end,
}

------------------------------------------------------------------ ledger and trade

local WAY_NAME = { trade = 'Trade', grain = 'Grain', craft = 'Craft', faith = 'Faith' }

local function way_tier(way)
  local tier = 0
  for _, b in pairs(state.b) do
    local d = R.BUILD[b.kind]
    if b.left == 0 and d.way == way and d.tier > tier then tier = d.tier end
  end
  return tier
end

