------------------------------------------------------------------ the end and the chronicle

local function chronicle()
  return Save.decode(kit.read('chronicle.txt')) or {}
end

local function record_end()
  if state.recorded then return end
  local e = S.ending(state)
  local c = chronicle()
  c[#c + 1] = { name = state.name, char = state.valley.char, title = e.title, score = e.score,
                months = state.month - 1, diff = state.diff, seed = state.seed }
  kit.write('chronicle.txt', Save.encode(c))
  state.recorded = true
  save()
end

SCREENS['end'] = {
  draw = function(gg)
    record_end()
    local e = S.ending(state)
    header(gg, e.title, state.name)
    local y = 100
    for _, l in ipairs(e.lines) do y = para(gg, l, 16, y, 500, 'medium') + 6 end
    y = y + 10
    gg:text(16, y, 'Score ' .. e.score, { font = kit.font('large') })
    bottom_row(gg, { { 'New valley', function() start_game() end }, { 'Title', function() screen = 'title' end } })
  end,
  back = function() screen = 'title'; return true end,
}

local CHAR_NAME = { plain = 'a fertile plain', hills = 'rocky hills', river = 'a wide river', marsh = 'marshland' }

SCREENS.chronicle = {
  draw = function(gg)
    local c = chronicle()
    header(gg, 'Chronicle', #c .. ' village' .. (#c == 1 and '' or 's') .. ' so far')
    local per = 6
    local pages = math.max(1, (#c + per - 1) // per)
    page = math.max(1, math.min(page, pages))
    local y = 92
    local f = kit.font('small')
    for k = #c - (page - 1) * per, math.max(1, #c - page * per + 1), -1 do
      local e = c[k]
      gg:text(16, y, fit(e.name .. ': ' .. e.title, kit.font('medium'), W - 32), { font = kit.font('medium') })
      gg:text(16, y + 32, fit('Score ' .. e.score .. ' · ' .. (CHAR_NAME[e.char] or e.char) .. ' · ' .. e.diff .. ' · '
        .. e.months .. ' months', f, W - 32), { font = f })
      y = y + 96
    end
    if #c == 0 then para(gg, 'No village has finished its ten years yet.', 16, 100, 200) end
    bottom_row(gg, { { '<', function() page = page - 1 end }, { '>', function() page = page + 1 end },
                     { 'Back', function() screen = 'title' end } })
  end,
  back = function() screen = 'title'; return true end,
}

SCREENS.settings = {
  draw = function(gg)
    header(gg, 'Settings', 'The difficulty applies to the next valley')
    local y = 110
    gg:text(16, y, 'Difficulty', { font = kit.font('medium') })
    y = y + 36
    local bw = (W - 48) // 3
    for k, d in ipairs({ { 'Gentle', 'gentle' }, { 'Normal', 'normal' }, { 'Harsh', 'harsh' } }) do
      local key = d[2]
      button(gg, 16 + (k - 1) * (bw + 8), y, bw, 56, d[1], function() prefs.diff = key; save() end,
        { line_width = (prefs.diff or 'normal') == key and 4 or 1 })
    end
    y = y + 72
    y = para(gg, 'Gentle: steadier harvests, milder winters, fewer hard times. Harsh: poorer harvests, hungry winters, '
      .. 'floods and hard times more often.', 16, y, y + 120) + 20
    button(gg, 16, y, W - 32, 60, 'New valley', new_valley)
    bottom_row(gg, { { 'Back', function() screen = 'title' end } })
  end,
  back = function() screen = 'title'; return true end,
}

------------------------------------------------------------------ host callbacks

function on_draw(c, gg)
  if not gg then return end
  local ok, e = pcall(function()
    gg:clear(0)
    hits = {}
    SCREENS[screen].draw(gg)
    if kit.modal() then hits = {}; kit.draw_modal(gg) end
    if ERR then gg:text(12, H - 28, kit.short('ERR ' .. ERR, 48), { font = kit.font('small') }) end
  end)
  if not ok then pcall(function() gg:text(12, H - 28, kit.short('ERR ' .. tostring(e), 48), { font = kit.font('small') }) end) end
end

local function tap(x, y)
  if kit.tap_modal(x, y) then return end
  local s = SCREENS[screen]
  if s.tap_map and s.tap_map(x, y) then return end
  for k = #hits, 1, -1 do
    local h = hits[k]
    if x >= h.x and x < h.x + h.w and y >= h.y and y < h.y + h.h then
      hits = {}           -- until the next frame: a second tap on the old screen does nothing
      h.fn()
      return
    end
  end
end

function on_input(c, ev)
  ERR = nil
  local handled = true
  local ok, e = pcall(function()
    if type(ev) ~= 'table' then return end
    if ev.type == 'pointer' and ev.phase == 'up' then
      tap(ev.x or 0, ev.y or 0)
      kit.refresh()
    elseif ev.type == 'key' and ev.key == 'back' then
      if ev.phase ~= 'up' and ev.phase ~= nil then return end
      if kit.modal() then
        if kit.modal().cancel then kit.modal().cancel() end
      else
        handled = SCREENS[screen].back() ~= false
      end
      kit.refresh()
    end
  end)
  if not ok then ERR = tostring(e); kit.refresh() end
  if state and layer_ok and map_dirty then pcall(rebuild_layer) end
  return handled
end

local function load()
  prefs = Save.decode(kit.read('prefs.txt')) or { diff = 'normal' }
  read_saved()
  screen = 'title'
end

function on_load(c)
  local ok, e = pcall(load)
  if not ok then ERR = tostring(e) end
end

function on_leave() pcall(save) end

if rawget(_G, '__TEST') then
  __TEST.api = {
    screen = function() return screen end,
    state = function() return state end,
    mod = mod,
    layer_ok = function() return layer_ok end,
    tile_xy = function(i) return tile_xy(i) end,
    modal_open = function() return kit.modal() ~= nil end,
    modal_pick = function(n) local m = kit.modal(); local row = m.rows[n or 1]; row[1][2]() end,
    show_event = function() show_event() end,
  }
end
